(function () {
  "use strict";

  var legacyAsset = "data:image/png;base64,";
  var defaultAsset = "data:image/png;base64,";
  var latestToken = 0;
  var pendingSource = "";
  var pendingColor = "";
  var pendingPromise = null;
  var cachedSource = "";
  var cachedColor = "";
  var cachedData = "";

  function safeColor(value) {
    var color = String(value || "").trim();
    return /^#[0-9a-f]{6}$/i.test(color) ? color : "#355a58";
  }

  function tint(source, color) {
    source = String(source || "");
    color = safeColor(color);
    if (!source) return Promise.resolve("");
    if (cachedSource === source && cachedColor === color && cachedData) return Promise.resolve(cachedData);
    if (pendingPromise && pendingSource === source && pendingColor === color) return pendingPromise;

    var token = ++latestToken;
    pendingSource = source;
    pendingColor = color;
    pendingPromise = new Promise(function (resolve, reject) {
      var image = new Image();
      image.onload = function () {
        try {
          var canvas = document.createElement("canvas");
          canvas.width = image.naturalWidth || image.width;
          canvas.height = image.naturalHeight || image.height;
          var context = canvas.getContext("2d", { alpha: true });
          context.clearRect(0, 0, canvas.width, canvas.height);
          context.drawImage(image, 0, 0);
          context.globalCompositeOperation = "source-in";
          context.fillStyle = color;
          context.fillRect(0, 0, canvas.width, canvas.height);
          context.globalCompositeOperation = "source-over";
          resolve(canvas.toDataURL("image/png"));
        } catch (error) { reject(error); }
      };
      image.onerror = function () { reject(new Error("Railway logo artwork could not be decoded.")); };
      image.src = source;
    }).then(function (dataUrl) {
      if (token === latestToken) {
        cachedSource = source;
        cachedColor = color;
        cachedData = dataUrl;
      }
      return dataUrl;
    }).finally(function () {
      if (token === latestToken) {
        pendingPromise = null;
        pendingSource = "";
        pendingColor = "";
      }
    });
    return pendingPromise;
  }

  window.LOG_TICKET_TRAIN_LOGO_LEGACY_ASSET = legacyAsset;
  window.LOG_TICKET_TRAIN_LOGO_ASSET = defaultAsset;
  window.LOG_TICKET_TRAIN_LOGO_RENDERER = { tint: tint };
})();
